@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Bricolage+Grotesque:wght@600;700;800&display=swap');
.mfp.mfp-crg.mfp-native-generated {--crg-primary:#1B4F8C;--crg-accent:#0F3564;--crg-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--crg-text:var(--mf-page-text,var(--mf-preset-text,#1A1F2B));--crg-muted:var(--mf-page-muted,var(--mf-preset-muted,#6B7280));--crg-border:var(--mf-page-border,var(--mf-preset-border,#DDE3EC));--crg-on-primary:var(--mf-preset-on-primary,#FFFFFF);--crg-deco:#EAF1FA;--crg-page:#F4F6F9;--crg-fill:#F4F6F9;--crg-fill-strong:color-mix(in srgb, var(--crg-text) 9%, var(--crg-surface));--crg-soft:color-mix(in srgb, var(--crg-primary) 12%, var(--crg-surface));--crg-hairline:color-mix(in srgb, var(--crg-text) 12%, var(--crg-surface));}.mfp.mfp-crg.mfp-native-generated {background:transparent!important;border:0!important;padding:0!important;font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif}.mfp.mfp-crg.mfp-native-generated {--crg-primary:var(--mf-page-primary,var(--mf-preset-primary,#1B4F8C));--crg-accent:var(--mf-page-accent,var(--mf-preset-accent,#0F3564));--crg-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--crg-text:var(--mf-page-text,var(--mf-preset-text,#1A1F2B));--crg-border:var(--mf-page-border,var(--mf-preset-border,#DDE3EC));--crg-on-primary:var(--mf-page-on-primary,var(--mf-preset-on-primary,#FFFFFF));--crg-page:var(--mf-preset-bg,#F4F6F9);}@container (max-width:520px){.mfp.mfp-crg.mfp-native-generated [class*="-grid"],.mfp.mfp-crg.mfp-native-generated [class*="-meta"],.mfp.mfp-crg.mfp-native-generated [class*="-scores"],.mfp.mfp-crg.mfp-native-generated [class*="-charts"],.mfp.mfp-crg.mfp-native-generated [class*="-cols"]{grid-template-columns:1fr!important}.mfp.mfp-crg.mfp-native-generated [class*="-body"],.mfp.mfp-crg.mfp-native-generated [class*="-split"],.mfp.mfp-crg.mfp-native-generated [class*="-foot"],.mfp.mfp-crg.mfp-native-generated [class*="-head"],.mfp.mfp-crg.mfp-native-generated [class*="-row"]{flex-wrap:wrap!important}.mfp.mfp-crg.mfp-native-generated [class*="-aside"],.mfp.mfp-crg.mfp-native-generated [class*="-side"]{flex:1 1 100%!important;width:100%!important;max-width:none!important}}.mfp.mfp-crg.mfp-native-generated  img{max-width:100%!important;height:auto}.mfp.mfp-crg.mfp-native-generated {overflow-wrap:break-word}

/* The wrapper itself: strip the host's card, but NOT its width. Layout > Max width in the module
   settings (480/640/768/960/Full) is a max-width on THIS element, and the previous version of this
   rule overrode it with max-width:none!important - so picking 960 did nothing at all. */
.mf-form-wrapper:has(.mfp-crg){background:transparent!important;border:0!important;
  border-radius:0!important;box-shadow:none!important;padding:0!important}
/* The boxes INSIDE it have their own measures, and those are what squeezed the design. */
.mf-form-wrapper:has(.mfp-crg) > .mf-form-inner,
.mf-form-wrapper:has(.mfp-crg) .mf-form,
.mf-form-wrapper:has(.mfp-crg) .mf-fields-container{background:transparent!important;
  border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important;
  margin:0!important;max-width:none!important;width:100%!important}

.mfp.mfp-crg.mfp-native-generated {container-type:inline-size;font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif!important;color:#1A1F2B}
.mfp.mfp-crg.mfp-native-generated .crg-page{padding:40px 0;background:#F4F6F9}
.mfp.mfp-crg.mfp-native-generated .crg-shell{max-width:768px;margin:0 auto;padding:0 16px}
.mfp.mfp-crg.mfp-native-generated .crg-back{font-size:16px;line-height:24px}
.mfp.mfp-crg.mfp-native-generated .crg-back-link{display:inline-flex;align-items:center;gap:6px;margin-bottom:24px;font-size:12px;
  line-height:16px;font-weight:500;color:#6B7280}
.mfp.mfp-crg.mfp-native-generated .crg-back-ico{display:block;flex:0 0 14px;width:14px;height:14px;
  background:url("data:image/svg+xml,%3Csvg xmlns='http:%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='%236B7280' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M19 12H5'%2F%3E%3Cpath d='m12 19-7-7 7-7'%2F%3E%3C%2Fsvg%3E") center/14px 14px no-repeat}
.mfp.mfp-crg.mfp-native-generated .crg-card{position:relative;overflow:hidden;border:1px solid #DDE3EC;border-radius:16px;
  background:#fff;box-shadow:0 1px 2px 0 rgba(0,0,0,.05)}
/* Two crisp layered wedges complete the rounded corner without an encoded SVG seam. */
.mfp.mfp-crg.mfp-native-generated .crg-tri-a{position:absolute;left:0;top:0;width:112px;height:68px;pointer-events:none;
  background:#1B4F8C;clip-path:polygon(0 0,100% 0,0 100%);opacity:.92}
.mfp.mfp-crg.mfp-native-generated .crg-tri-a::after{content:'';position:absolute;left:0;top:0;width:62px;height:36px;
  background:#EAF1FA;clip-path:polygon(0 0,100% 0,0 100%)}
.mfp.mfp-crg.mfp-native-generated .crg-tri-b{position:absolute;left:0;bottom:0;width:160px;height:64px;pointer-events:none;
  background:rgba(27,79,140,.12);clip-path:polygon(0 100%,56% 100%,0 0)}

/* header ----------------------------------------------------------------- */
.mfp.mfp-crg.mfp-native-generated .crg-head{position:relative;display:flex;align-items:flex-start;justify-content:space-between;
  gap:24px;padding:40px 32px 24px}
@container (min-width:640px){.mfp.mfp-crg.mfp-native-generated .crg-head{padding:40px 40px 24px}}
.mfp.mfp-crg.mfp-native-generated .crg-who{display:flex;align-items:center;gap:16px}
.mfp.mfp-crg.mfp-native-generated .crg-avatar{flex:0 0 64px;width:64px;height:64px;border:4px solid #EAF1FA;border-radius:999px;
  position:relative;overflow:hidden;
  background-image:url('/DesktopModules/MegaForm/Assets/img/corporate-registration-blue/registration-avatar.png'),url('/Modules/MegaForm/img/corporate-registration-blue/registration-avatar.png');
  background-size:cover;background-position:50% 50%}
.mfp.mfp-crg.mfp-native-generated img.crg-content-image{position:absolute!important;inset:0!important;display:block!important;
  width:100%!important;height:100%!important;object-fit:cover!important;object-position:50% 50%!important;
  border:0!important;border-radius:999px!important;pointer-events:none!important}
.mfp.mfp-crg.mfp-native-generated .crg-kicker{font-size:11px;line-height:1.5;font-weight:600;letter-spacing:.1em;
  text-transform:uppercase;color:#1B4F8C}
.mfp.mfp-crg.mfp-native-generated .crg-h1{font-family:'Bricolage Grotesque','Inter',system-ui,-apple-system,'Segoe UI',sans-serif!important;font-size:24px;line-height:32px;
  font-weight:700;color:#1A1F2B}
.mfp.mfp-crg.mfp-native-generated .crg-co{text-align:right}
.mfp.mfp-crg.mfp-native-generated .crg-co-row{display:flex;align-items:center;justify-content:flex-end;gap:8px}
.mfp.mfp-crg.mfp-native-generated .crg-co-mark{display:flex;align-items:center;justify-content:center;width:28px;height:28px;
  border-radius:4px;background:#1B4F8C}
.mfp.mfp-crg.mfp-native-generated .crg-co-dia{display:block;width:12px;height:12px;transform:rotate(45deg);background:#fff}
.mfp.mfp-crg.mfp-native-generated .crg-co-n{font-family:'Bricolage Grotesque','Inter',system-ui,-apple-system,'Segoe UI',sans-serif!important;font-size:14px;line-height:20px;
  font-weight:700;letter-spacing:.025em;color:#1A1F2B}
.mfp.mfp-crg.mfp-native-generated .crg-co-tag{margin-top:2px;font-size:10px;line-height:15px;font-weight:400;
  letter-spacing:.1em;color:#6B7280}
.mfp.mfp-crg.mfp-native-generated .crg-co-date{margin-top:12px}
/* The header column is shrink-to-fit, so in the mock its width comes from the ONE thing with an
   intrinsic size: Chrome renders a native date input 156px wide at this padding/font (w-40 loses
   to w-full, both are on the element). Our renderer emits a text input, whose intrinsic width is
   different, so state that 156 outright or the whole right column lands 4px off. */
.mfp.mfp-crg.mfp-native-generated .crg-co-date .mf-input[class]{width:100%!important;min-width:156px}

/* body ------------------------------------------------------------------- */
.mfp.mfp-crg.mfp-native-generated .crg-body{position:relative;padding:32px}
@container (min-width:640px){.mfp.mfp-crg.mfp-native-generated .crg-body{padding:32px 40px}}
.mfp.mfp-crg.mfp-native-generated .crg-cap{display:flex;align-items:center;gap:12px;margin-bottom:16px}
.mfp.mfp-crg.mfp-native-generated .crg-cap-t{font-size:11px;line-height:1.5;font-weight:700;letter-spacing:.1em;
  text-transform:uppercase;color:#1B4F8C}
.mfp.mfp-crg.mfp-native-generated .crg-hair{flex:1 1 0;height:1px;display:block;background:#DDE3EC}
.mfp.mfp-crg.mfp-native-generated .crg-grid2{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:32px}
.mfp.mfp-crg.mfp-native-generated .crg-grid-last{margin-bottom:8px}
.mfp.mfp-crg.mfp-native-generated .crg-span2{grid-column:1/-1}
.mfp.mfp-crg.mfp-native-generated .crg-field{display:block;margin:0}
.mfp.mfp-crg.mfp-native-generated .crg-label{display:block;margin:0 0 6px;font-size:12px;line-height:18px;font-weight:600;
  letter-spacing:.025em;text-transform:uppercase;color:#6B7280}
.mfp.mfp-crg.mfp-native-generated p.crg-note{margin:24px 0 0!important;font-size:11px!important;line-height:1.625!important;
  font-weight:400!important;color:#6B7280!important}

/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-crg.mfp-native-generated label,.mfp.mfp-crg.mfp-native-generated span,.mfp.mfp-crg.mfp-native-generated p,.mfp.mfp-crg.mfp-native-generated div,.mfp.mfp-crg.mfp-native-generated ul,.mfp.mfp-crg.mfp-native-generated li,.mfp.mfp-crg.mfp-native-generated h1,.mfp.mfp-crg.mfp-native-generated h2,.mfp.mfp-crg.mfp-native-generated h3,.mfp.mfp-crg.mfp-native-generated button{font-family:inherit!important}
.mfp.mfp-crg.mfp-native-generated .mf-field-label{display:none!important}
/* A wizard's page-break Section renders a visible heading the mock has no room for - it exists to
   split the pages, not to be seen. */
.mfp.mfp-crg.mfp-native-generated .mf-section-break,.mfp.mfp-crg.mfp-native-generated .mf-section-title{display:none!important}
.mfp.mfp-crg.mfp-native-generated .mf-field-group{margin:0!important;width:100%}
.mfp.mfp-crg.mfp-native-generated .mf-form-title,.mfp.mfp-crg.mfp-native-generated .mf-form-description,.mfp.mfp-crg.mfp-native-generated .mf-form-actions{display:none!important}
.mfp.mfp-crg.mfp-native-generated .mf-option-item{margin:0!important}
/* megaform gives every option chip a 36px floor and paints .mf-option-icon as a rounded tile. */
.mfp.mfp-crg.mfp-native-generated .mf-option-group--chips .mf-option-check,
.mfp.mfp-crg.mfp-native-generated .mf-option-group--cards .mf-option-check{display:none!important}
.mfp.mfp-crg.mfp-native-generated .mf-option-group--chips .mf-option-ui{min-height:0!important;height:auto!important}
.mfp.mfp-crg.mfp-native-generated .mf-option-group--cards .mf-option-copy{display:block;width:100%}


.mfp.mfp-crg.mfp-native-generated .mf-input[class],.mfp.mfp-crg.mfp-native-generated .mf-select[class]{width:100%!important;box-sizing:border-box!important;
  border:1px solid #DDE3EC!important;border-radius:8px!important;background:#FFFFFF!important;
  padding:10px 14px!important;min-height:0!important;height:auto!important;
  color:rgb(8,12,15)!important;font-family:inherit!important;font-size:14px!important;
  line-height:20px!important;font-weight:400!important;box-shadow:none!important}
.mfp.mfp-crg.mfp-native-generated .mf-input[class]:focus,.mfp.mfp-crg.mfp-native-generated .mf-select[class]:focus{border-color:#1B4F8C!important;
  box-shadow:none!important;outline:none!important}
.mfp.mfp-crg.mfp-native-generated .mf-input[class]::placeholder,.mfp.mfp-crg.mfp-native-generated .mf-textarea[class]::placeholder{color:#94A3B8!important;opacity:1}
.mfp.mfp-crg.mfp-native-generated .mf-select[class]:invalid,
.mfp.mfp-crg.mfp-native-generated .mf-select[class]:has(option[value=""]:checked){color:#94A3B8!important}

/* Date renders as a composite button in both products. Pin its paper chrome too; otherwise the
   host's dark button rule survives even when ordinary inputs have been corrected. */
.mfp.mfp-crg.mfp-native-generated .crg-field .mf-cal[class]{width:100%!important;box-sizing:border-box!important;
  border:1px solid #DDE3EC!important;border-radius:8px!important;background:#FFFFFF!important;
  min-height:42px!important;color:rgb(8,12,15)!important;box-shadow:none!important}

/* gender pills ----------------------------------------------------------- */
.mfp.mfp-crg.mfp-native-generated .mf-option-group--chips{display:flex;flex-wrap:wrap;gap:8px}
.mfp.mfp-crg.mfp-native-generated .mf-option-group--chips .mf-option-ui{display:block;gap:0;padding:6px 16px;
  border:1px solid #DDE3EC;border-radius:9999px;background:#fff;color:#6B7280;font-size:12px;
  line-height:16px;font-weight:600;text-align:center;cursor:pointer;transition:all .15s ease}
.mfp.mfp-crg.mfp-native-generated .mf-option-group--chips .mf-option-label{font-size:12px;line-height:16px;font-weight:600;
  color:inherit}
.mfp.mfp-crg.mfp-native-generated .mf-option-group--chips .mf-option-item.is-selected .mf-option-ui,
.mfp.mfp-crg.mfp-native-generated .mf-option-group--chips input:checked+.mf-option-ui{background:#1B4F8C;border-color:#1B4F8C;
  color:#fff}

/* Date controls. The mock uses a NATIVE date input; our renderer swaps in a button plus a popover,
   so restate what the native control gives the mock for free: ink-coloured text set in 4px from
   the padding edge, and a 10x12 black indicator whose right edge sits 20px off the border.
   Both rules must outrank megaform's own .mf-cal.is-empty and .mf-cal .mf-date-icon. */
.mfp.mfp-crg.mfp-native-generated .crg-field .mf-cal.is-empty .mf-cal-value,.mfp.mfp-crg.mfp-native-generated .crg-field .mf-cal-value{
  color:rgb(8,12,15)!important;padding-left:4px;padding-right:24px}
.mfp.mfp-crg.mfp-native-generated .crg-field .mf-cal .mf-date-icon{position:absolute!important;right:20px!important;
  width:10px!important;height:12px!important;flex:0 0 10px!important;color:#000!important}
.mfp.mfp-crg.mfp-native-generated .crg-field .mf-cal .mf-date-icon svg{width:10px!important;height:12px!important;
  stroke-width:2!important}

/* CTA -------------------------------------------------------------------- */
.mfp.mfp-crg.mfp-native-generated .crg-cta{display:flex;justify-content:flex-end;margin-top:32px}
.mfp.mfp-crg.mfp-native-generated button.crg-submit[type="submit"]{display:inline-flex;align-items:center;gap:6px;
  width:auto!important;padding:10px 24px!important;border:0!important;border-radius:8px!important;
  background:linear-gradient(135deg,#1B4F8C,#0F3564)!important;color:#fff!important;
  font-family:inherit!important;font-size:14px!important;line-height:20px!important;
  font-weight:600!important;letter-spacing:normal!important;text-transform:none!important;
  cursor:pointer!important;box-shadow:none!important}
/* the mock fades a blocked CTA to 40% */
.mfp.mfp-crg.mfp-native-generated button.crg-submit .crg-chk{display:block;flex:0 0 16px;width:16px;height:16px;
  background:url("data:image/svg+xml,%3Csvg xmlns='http:%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='%23ffffff' stroke-width='3' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpath d='M20 6 9 17l-5-5'%2F%3E%3C%2Fsvg%3E") center/16px 16px no-repeat}
.mfp.mfp-crg.mfp-native-generated button.crg-submit.mf-nav-blocked,.mfp.mfp-crg.mfp-native-generated button.crg-submit[disabled]{opacity:.4!important;
  background:linear-gradient(135deg,#1B4F8C,#0F3564)!important;cursor:not-allowed!important}

/* The source mock has no mobile header treatment and clips its company/date column at 390px.
   MegaForm must remain usable in narrower CMS panes, including Oqtane's 230px home column. */
@container (max-width:520px){
.mfp.mfp-crg.mfp-native-generated .crg-tri-a{width:84px;height:52px}
.mfp.mfp-crg.mfp-native-generated .crg-tri-a::after{width:46px;height:28px}
.mfp.mfp-crg.mfp-native-generated .crg-head{flex-direction:column!important;align-items:stretch!important;gap:20px!important;
  padding:32px 20px 22px!important}
.mfp.mfp-crg.mfp-native-generated .crg-who{min-width:0;gap:12px}
.mfp.mfp-crg.mfp-native-generated .crg-avatar{flex-basis:56px;width:56px;height:56px}
.mfp.mfp-crg.mfp-native-generated .crg-who-t{min-width:0}
.mfp.mfp-crg.mfp-native-generated .crg-h1{font-size:22px;line-height:28px;overflow-wrap:normal}
.mfp.mfp-crg.mfp-native-generated .crg-co{width:100%;text-align:left}
.mfp.mfp-crg.mfp-native-generated .crg-co-row{justify-content:flex-start}
.mfp.mfp-crg.mfp-native-generated .crg-co-date{width:100%;margin-top:14px}
.mfp.mfp-crg.mfp-native-generated .crg-co-date .mf-input[class],.mfp.mfp-crg.mfp-native-generated .crg-co-date .mf-cal[class]{width:100%!important;
  min-width:0!important}
.mfp.mfp-crg.mfp-native-generated .crg-body{padding:26px 20px!important}
.mfp.mfp-crg.mfp-native-generated .crg-grid2{grid-template-columns:minmax(0,1fr)!important;gap:18px;margin-bottom:28px}
.mfp.mfp-crg.mfp-native-generated .crg-span2{grid-column:auto}
.mfp.mfp-crg.mfp-native-generated .crg-cap{gap:8px}
.mfp.mfp-crg.mfp-native-generated .crg-cap-t{max-width:calc(100% - 20px)}
.mfp.mfp-crg.mfp-native-generated .crg-cta{margin-top:28px}
.mfp.mfp-crg.mfp-native-generated button.crg-submit[type="submit"]{justify-content:center;width:100%!important;padding-left:14px!important;
  padding-right:14px!important}
}
.mfp.mfp-crg.mfp-native-generated .crg-page{padding:0!important;background:transparent!important;min-height:0!important}.mfp.mfp-crg.mfp-native-generated .crg-shell,.mfp.mfp-crg.mfp-native-generated .crg-wrap{max-width:none!important;margin:0!important}.mfp.mfp-crg.mfp-native-generated .crg-grid,.mfp.mfp-crg.mfp-native-generated .crg-main,.mfp.mfp-crg.mfp-native-generated .crg-hero-in,.mfp.mfp-crg.mfp-native-generated .crg-card{max-width:none!important;margin-left:0!important;margin-right:0!important}
